\set ON_ERROR_STOP on
BEGIN;
CREATE TEMP TABLE map86(lesson_id bigint, expected_url text, old_title text, new_title text) ON COMMIT DROP;
DO $check$
DECLARE n int;
BEGIN
 IF (SELECT count(*) FROM map86) <> 56 THEN RAISE EXCEPTION 'Expected 56 source mappings';END IF;
 SELECT count(*) INTO n FROM map86 m LEFT JOIN lms.lesson_resources r ON r.lesson_id=m.lesson_id AND r.resource_type='PDF' AND r.resource_url=m.expected_url WHERE r.lesson_id IS NULL;
 IF n>0 THEN RAISE EXCEPTION 'Missing % PDF source links; rollback', n;END IF;
 SELECT count(*) INTO n FROM map86 m JOIN lms.lesson_resources r ON r.lesson_id=m.lesson_id AND r.resource_type='PDF' AND r.resource_url=m.expected_url WHERE r.title NOT IN (m.old_title,m.new_title);
 IF n>0 THEN RAISE EXCEPTION 'Found % unexpected custom PDF titles; rollback',n;END IF;
 RAISE NOTICE 'All 56 links exist; no source URLs or PDF files will change';
END $check$;
UPDATE lms.lesson_resources r SET title=m.new_title FROM map86 m WHERE r.lesson_id=m.lesson_id AND r.resource_type='PDF' AND r.resource_url=m.expected_url AND r.title IS DISTINCT FROM m.new_title;
DO $verify$
BEGIN
 IF EXISTS(SELECT 1 FROM map86 m WHERE NOT EXISTS (SELECT 1 FROM lms.lesson_resources r WHERE r.lesson_id=m.lesson_id AND r.resource_type='PDF' AND r.resource_url=m.expected_url AND r.title=m.new_title)) THEN RAISE EXCEPTION 'Title verification failed'; END IF;
 RAISE NOTICE '56/56 references now show verified real chapters or honest general-source labels';
END $verify$;
COMMIT;
